func ptrCaptureRequest(p unsafe.Pointer, c int32) any {
	r := (*capturerequest.CaptureRequest)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return (*string)(unsafe.Pointer(&r.DeviceID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Mode))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.TargetType
	case 8:
		return (*string)(unsafe.Pointer(&r.TargetID))
	case 9:
		return (**string)(unsafe.Pointer(&r.DocumentTypeID))
	case 10:
		return (**string)(unsafe.Pointer(&r.ProfileID))
	case 11:
		return &r.SourceName
	case 12:
		return (**string)(unsafe.Pointer(&r.BatchID))
	case 13:
		return (*string)(unsafe.Pointer(&r.FailureCode))
	case 14:
		return &r.FailureMessage
	case 15:
		return &r.ExpiresAt
	case 16:
		return &r.DeliveredAt
	case 17:
		return &r.CompletedAt
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueCaptureRequest(p unsafe.Pointer, c int32) any {
	r := (*capturerequest.CaptureRequest)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.UserID)
	case 4:
		return string(r.DeviceID)
	case 5:
		return string(r.Mode)
	case 6:
		return string(r.Status)
	case 7:
		return r.TargetType
	case 8:
		return string(r.TargetID)
	case 9:
		if r.DocumentTypeID == nil {
			return nil
		}
		return string(*r.DocumentTypeID)
	case 10:
		if r.ProfileID == nil {
			return nil
		}
		return string(*r.ProfileID)
	case 11:
		if r.SourceName == "" {
			return nil
		}
		return r.SourceName
	case 12:
		if r.BatchID == nil {
			return nil
		}
		return string(*r.BatchID)
	case 13:
		if r.FailureCode == "" {
			return nil
		}
		return string(r.FailureCode)
	case 14:
		if r.FailureMessage == "" {
			return nil
		}
		return r.FailureMessage
	case 15:
		return r.ExpiresAt
	case 16:
		if r.DeliveredAt == nil {
			return nil
		}
		return *r.DeliveredAt
	case 17:
		if r.CompletedAt == nil {
			return nil
		}
		return *r.CompletedAt
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

